  const a = cam.tilt || 0, r = cam.rot || 0, s = cam.spin || 0;
  let R = [1, 0, 0], U = [0, Math.cos(a), Math.sin(a)], F = [0, -Math.sin(a), Math.cos(a)];
  const cr = Math.cos(r), sr = Math.sin(r);
